"""Traceability matrix and validation summary rendering."""

from __future__ import annotations

import html

DISCLAIMER = (
    "This package is supporting evidence generated by part11-eval-evidence. The tool is not "
    "itself a 21 CFR Part 11 compliant system, does not provide electronic signatures or access "
    "control, and is not legal or regulatory advice."
)


def trace_matrix(requirements: list[dict], results: list[dict]) -> list[dict]:
    by_req: dict[str, list[dict]] = {}
    for r in results:
        by_req.setdefault(r["requirement_id"], []).append(r)
    rows = []
    for req in requirements:
        tests = by_req.get(req["id"], [])
        if not tests:
            status = "NOT TESTED"
        elif all(t["verdict"] == "pass" for t in tests):
            status = "PASS"
        else:
            status = "FAIL"
        rows.append({
            "requirement_id": req["id"],
            "description": req.get("description", ""),
            "risk": req.get("risk", ""),
            "tests": [t["test_id"] for t in tests],
            "passed": sum(t["verdict"] == "pass" for t in tests),
            "total": len(tests),
            "status": status,
        })
    known = {r["id"] for r in requirements}
    for rid, tests in by_req.items():
        if rid not in known:
            rows.append({"requirement_id": rid, "description": "(not in requirements file)",
                         "risk": "", "tests": [t["test_id"] for t in tests],
                         "passed": sum(t["verdict"] == "pass" for t in tests),
                         "total": len(tests), "status": "UNTRACED"})
    return rows


def deviations(results: list[dict], matrix: list[dict]) -> list[str]:
    out = [f"Test {r['test_id']} ({r['requirement_id']}): verdict {r['verdict'].upper()}"
           for r in results if r["verdict"] != "pass"]
    out += [f"Requirement {m['requirement_id']}: {m['status']}" for m in matrix
            if m["status"] in ("NOT TESTED", "UNTRACED")]
    return out


def matrix_markdown(matrix: list[dict]) -> str:
    lines = ["| Requirement | Description | Risk | Tests | Passed | Status |",
             "|---|---|---|---|---|---|"]
    for m in matrix:
        lines.append(f"| {m['requirement_id']} | {m['description']} | {m['risk']} | "
                     f"{', '.join(m['tests']) or '-'} | {m['passed']}/{m['total']} | "
                     f"{m['status']} |")
    return "\n".join(lines)


def dispositions_markdown(dispositions: list[dict]) -> str:
    """Render disposition records as a markdown table (or a none line)."""
    if not dispositions:
        return "None recorded."
    lines = [
        "| ID | Requirement | Test | Disposition | Approver | Approved at |",
        "|---|---|---|---|---|---|",
    ]
    for d in dispositions:
        lines.append(
            f"| {d['deviation_id']} | {d.get('requirement_id') or '-'} | "
            f"{d.get('test_id') or '-'} | {d['disposition']} | {d['approver']} | "
            f"{d['approved_at']} |"
        )
    detail = []
    for d in dispositions:
        detail += [
            f"### {d['deviation_id']}",
            "",
            f"- Description: {d['description'].strip()}",
            f"- Root cause: {d['root_cause'].strip()}",
            f"- Rationale: {d['disposition_rationale'].strip()}",
            "",
        ]
    return "\n".join(lines) + "\n\n" + "\n".join(detail)


def summary_markdown(meta: dict, matrix: list[dict], devs: list[str],
                     dispositions: list[dict] | None = None) -> str:
    verdict = "PASS" if all(m["status"] == "PASS" for m in matrix) else "FAIL"
    banner = f"> **{meta['label']}**\n\n" if meta.get("label") else ""
    md = [f"# Validation Summary: {meta['run_id']}", "", banner.rstrip(), "",
          "## Run metadata", "",
          f"- Operator: {meta['operator']}",
          f"- Generated (UTC): {meta['generated_at']}",
          f"- Model(s): {', '.join(meta['models'])}",
          f"- Config SHA-256: `{meta['config_hash']}`",
          f"- Results file SHA-256: `{meta['results_hash']}`",
          f"- Requirements file SHA-256: `{meta['requirements_hash']}`",
          f"- Run log final hash: `{meta['chain_head']}`",
          f"- Tests executed: {meta['n_tests']}", "",
          f"## Overall result: **{verdict}**", "",
          "## Pass/fail by requirement", "", matrix_markdown(matrix), "",
          "## Deviations", ""]
    md += [f"- {d}" for d in devs] or ["- None"]
    md += ["", "## Deviation dispositions", "",
           dispositions_markdown(dispositions or []), ""]
    md += ["", "## Review", "", "Reviewed by: ____________  Date: ________  (manual sign-off; "
           "this tool does not implement Part 11 electronic signatures)", "", "---", "",
           f"_{DISCLAIMER}_", ""]
    return "\n".join(x for x in md if x is not None)


def summary_html(md_text: str) -> str:
    """Minimal, dependency-free HTML wrapper (pre-formatted markdown) for printing/archiving."""
    return ("<!doctype html><html><head><meta charset='utf-8'><title>Validation Summary</title>"
            "<style>body{font-family:system-ui,sans-serif;max-width:900px;margin:2em auto}"
            "pre{white-space:pre-wrap}</style></head><body><pre>"
            + html.escape(md_text) + "</pre></body></html>")


_CSS = (
    "body{font-family:system-ui,sans-serif;max-width:960px;margin:2em auto;color:#1b1f24}"
    "table{border-collapse:collapse;width:100%;margin:1em 0}"
    "th,td{border:1px solid #d0d7de;padding:6px 8px;text-align:left;vertical-align:top}"
    "th{background:#f6f8fa}code{font-size:.85em;word-break:break-all}"
    ".banner{background:#fff8c5;border:1px solid #d4a72c;padding:8px 12px}"
    ".PASS{color:#1a7f37;font-weight:600}.FAIL{color:#cf222e;font-weight:600}"
    ".NOT.TESTED,.UNTRACED{color:#9a6700;font-weight:600}"
    ".sign{margin-top:2em;border-top:1px solid #d0d7de;padding-top:1em}"
    "@media print{body{margin:0}th{background:#eee}}"
)


def _status(s: str) -> str:
    return f"<span class='{html.escape(s)}'>{html.escape(s)}</span>"


def summary_html_report(meta: dict, matrix: list[dict], devs: list[str],
                        dispositions: list[dict] | None = None) -> str:
    """Self-contained, print-friendly HTML validation summary (no external assets)."""
    e = html.escape
    verdict = "PASS" if all(m["status"] == "PASS" for m in matrix) else "FAIL"
    meta_rows = [
        ("Operator", e(str(meta["operator"]))),
        ("Generated (UTC)", e(str(meta["generated_at"]))),
        ("Model(s)", e(", ".join(meta["models"]))),
        ("Config SHA-256", f"<code>{e(meta['config_hash'])}</code>"),
        ("Results file SHA-256", f"<code>{e(meta['results_hash'])}</code>"),
        ("Requirements file SHA-256", f"<code>{e(meta['requirements_hash'])}</code>"),
        ("Run log final hash", f"<code>{e(meta['chain_head'])}</code>"),
        ("Tests executed", str(meta["n_tests"])),
    ]
    parts = [
        "<!doctype html><html lang='en'><head><meta charset='utf-8'>",
        f"<title>Validation Summary: {e(meta['run_id'])}</title><style>{_CSS}</style>",
        "</head><body>",
        f"<h1>Validation Summary: {e(meta['run_id'])}</h1>",
    ]
    if meta.get("label"):
        parts.append(f"<p class='banner'><strong>{e(meta['label'])}</strong></p>")
    parts.append("<h2>Run metadata</h2><table>")
    parts += [f"<tr><th>{k}</th><td>{v}</td></tr>" for k, v in meta_rows]
    parts.append(f"</table><h2>Overall result: {_status(verdict)}</h2>")
    parts.append("<h2>Pass/fail by requirement</h2><table><tr><th>Requirement</th>"
                 "<th>Description</th><th>Risk</th><th>Tests</th><th>Passed</th>"
                 "<th>Status</th></tr>")
    for m in matrix:
        parts.append(
            f"<tr><td>{e(m['requirement_id'])}</td><td>{e(m['description'])}</td>"
            f"<td>{e(str(m['risk']))}</td><td>{e(', '.join(m['tests']) or '-')}</td>"
            f"<td>{m['passed']}/{m['total']}</td><td>{_status(m['status'])}</td></tr>")
    parts.append("</table><h2>Deviations</h2><ul>")
    parts += [f"<li>{e(d)}</li>" for d in devs] or ["<li>None</li>"]
    parts.append("</ul><h2>Deviation dispositions</h2>")
    if dispositions:
        parts.append("<table><tr><th>ID</th><th>Requirement</th><th>Test</th>"
                     "<th>Disposition</th><th>Root cause</th><th>Approver</th>"
                     "<th>Approved at</th></tr>")
        for d in dispositions:
            parts.append(
                f"<tr><td>{e(d['deviation_id'])}</td>"
                f"<td>{e(d.get('requirement_id') or '-')}</td>"
                f"<td>{e(d.get('test_id') or '-')}</td>"
                f"<td>{e(d['disposition'])}</td>"
                f"<td>{e(d['root_cause'].strip())}</td>"
                f"<td>{e(d['approver'])}</td>"
                f"<td>{e(d['approved_at'])}</td></tr>")
        parts.append("</table>")
    else:
        parts.append("<p>None recorded.</p>")
    parts.append(
        "<div class='sign'><p>Reviewed by: ____________________ "
        "Date: ____________</p><p><em>Manual sign-off; this tool does not implement Part 11 "
        f"electronic signatures.</em></p></div><hr><p><small>{e(DISCLAIMER)}</small></p>"
        "</body></html>")
    return "\n".join(parts) + "\n"
